def flatten(report):
    cols=[c.get('ColTitle','') for c in report.get('Columns',{}).get('Column',[])]
    out=[]
    def walk(n):
        if isinstance(n,list):
            for x in n: walk(x)
        elif isinstance(n,dict):
            if n.get('type')=='Data':
                vals=[(cd.get('value') if isinstance(cd,dict) else cd) for cd in (n.get('ColData') or [])]
                out.append(dict(zip(cols,vals)))
            for x in ((n.get('Rows') or {}).get('Row') or []):
                walk(x)
    walk(((report.get('Rows') or {}).get('Row') or []))
    return out
